const news = $input.all().map(i => i.json);

const INDICES = {
  'economia': 'ECO',
  'politica': 'POL',
  'tecnologia': 'TEC',
  'saude': 'SAU',
  'educacao': 'EDU',
  'seguranca': 'SEG',
  'meio_ambiente': 'AMB',
  'internacional': 'INT',
  'esportes': 'ESP'
};

const grouped = {};
for (const article of news) {
  const cat = (article.category || 'outros').toLowerCase().replace(/ /g, '_');
  if (!grouped[cat]) grouped[cat] = { total: 0, count: 0 };
  grouped[cat].total += Number(article.score_brasil) || 0;
  grouped[cat].count += 1;
}

const weekStart = new Date();
weekStart.setDate(weekStart.getDate() - weekStart.getDay());
weekStart.setHours(0, 0, 0, 0);

const results = [];
for (const [cat, code] of Object.entries(INDICES)) {
  const data = grouped[cat] || { total: 0, count: 0 };
  results.push({
    json: {
      index_code: code,
      score: data.count > 0 ? Number((data.total / data.count).toFixed(2)) : 0,
      article_count: data.count,
      week_start: weekStart.toISOString()
    }
  });
}

return results;
